class URLHandler:
    COLON_SLASH_SLASH = "://"
    SLASH = "/"
    QUESTION_MARK = "?"
    HASH = "#"
    AMPERSAND = "&"
    EQUALS = "="

    def __init__(self, url):
        self._url = url

    @property
    def url(self):
        return self._url

    @url.setter
    def url(self, value):
        self._url = value

    def _find_scheme_end(self):
        return self.url.find(self.COLON_SLASH_SLASH)

    def _get_url_without_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self.url[scheme_end + len(self.COLON_SLASH_SLASH):]
        return None

    def _find_host_end(self, url_without_scheme):
        return url_without_scheme.find(self.SLASH)

    def get_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self.url[:scheme_end]
        return None

    def get_host(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is not None:
            host_end = self._find_host_end(url_without_scheme)
            if host_end != -1:
                return url_without_scheme[:host_end]
            return url_without_scheme
        return None

    def get_path(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is not None:
            host_end = self._find_host_end(url_without_scheme)
            if host_end != -1:
                return url_without_scheme[host_end:]
        return None

    def get_query_params(self):
        query_start = self.url.find(self.QUESTION_MARK)
        fragment_start = self.url.find(self.HASH)
        if query_start != -1:
            query_string = self.url[query_start + 1:fragment_start] if fragment_start != -1 else self.url[query_start + 1:]
            params = {}
            if query_string:
                param_pairs = query_string.split(self.AMPERSAND)
                for pair in param_pairs:
                    key_value = pair.split(self.EQUALS)
                    if len(key_value) == 2:
                        key, value = key_value
                        params[key] = value
            return params
        return None

    def get_fragment(self):
        fragment_start = self.url.find(self.HASH)
        if fragment_start != -1:
            return self.url[fragment_start + 1:]
        return None
